changeSet.sql:
-- 0. Контент командной памяти (scope=team удалён из модели) DELETE FROM persistent_memory_hot WHERE scope_id IN (SELECT scope_id FROM connections WHERE connector_code = 'persist-memory' AND identity_scope = 'TEAM' AND scope_id IS NOT NULL); DELETE FROM persistent_memory_cold WHERE scope_id IN (SELECT scope_id FROM connections WHERE connector_code = 'persist-memory' AND identity_scope = 'TEAM' AND scope_id IS NOT NULL);
-- 1. Каноническая строка-режим: старейшая активная connection кода у пользователя CREATE TABLE _migr_conn_canon AS SELECT DISTINCT ON (user_id, connector_code) user_id, connector_code, id AS canon_id FROM connections WHERE connector_code IN ('board','persist-memory','time','media','webchat','acp') AND deleted_at IS NULL ORDER BY user_id, connector_code, created_at, id;
-- 2. Дедуп привязок: у агента остаётся одна привязка на код коннектора (старейшая) UPDATE agent_connections SET deleted_at = CURRENT_TIMESTAMP WHERE id IN ( SELECT id FROM ( SELECT ac.id, ROW_NUMBER() OVER (PARTITION BY ac.agent_id, c.user_id, c.connector_code ORDER BY ac.created_at, ac.id) AS rn FROM agent_connections ac JOIN connections c ON c.id = ac.connection_id JOIN _migr_conn_canon m ON m.user_id = c.user_id AND m.connector_code = c.connector_code WHERE ac.deleted_at IS NULL AND c.deleted_at IS NULL ) ranked WHERE rn > 1);
-- Политики снятых привязок не должны осиротеть UPDATE agent_connection_policies SET deleted_at = CURRENT_TIMESTAMP WHERE deleted_at IS NULL AND agent_connection_id IN (SELECT id FROM agent_connections WHERE deleted_at IS NOT NULL);
-- 3. Дедуп SYSTEM-джоб: остаются строки канонической connection -- (uq_connector_jobs_connection: (connector_code, connection_id, name) WHERE kind='SYSTEM') DELETE FROM connector_jobs j USING connections c, _migr_conn_canon m WHERE j.kind = 'SYSTEM' AND j.connection_id = c.id::text AND m.user_id = c.user_id AND m.connector_code = c.connector_code AND c.id <> m.canon_id;
-- 4. Перевесить привязки, каналы и джобы на каноническую строку UPDATE agent_connections ac SET connection_id = m.canon_id FROM connections c, _migr_conn_canon m WHERE ac.connection_id = c.id AND ac.deleted_at IS NULL AND m.user_id = c.user_id AND m.connector_code = c.connector_code AND ac.connection_id <> m.canon_id;
UPDATE channels ch SET connection_id = m.canon_id FROM connections c, _migr_conn_canon m WHERE ch.connection_id = c.id AND ch.deleted_at IS NULL AND m.user_id = c.user_id AND m.connector_code = c.connector_code AND ch.connection_id <> m.canon_id;
UPDATE connector_jobs j SET connection_id = m.canon_id::text FROM connections c, _migr_conn_canon m WHERE j.connection_id = c.id::text AND m.user_id = c.user_id AND m.connector_code = c.connector_code AND j.connection_id <> m.canon_id::text;
-- 5. Неканонические строки внутренних коннекторов — soft-delete UPDATE connections c SET deleted_at = CURRENT_TIMESTAMP FROM _migr_conn_canon m WHERE m.user_id = c.user_id AND m.connector_code = c.connector_code AND c.deleted_at IS NULL AND c.id <> m.canon_id;
-- 6. Канонические строки: режим по типу коннектора, client handle = code_userId UPDATE connections c SET identity_scope = CASE c.connector_code WHEN 'board' THEN 'TEAM' WHEN 'persist-memory' THEN 'AGENT' ELSE 'USER' END, sub_code = NULL, full_code = c.connector_code || '_' || c.user_id FROM _migr_conn_canon m WHERE c.id = m.canon_id;
-- 7. Внешние экземпляры: INSTANCE/GLOBAL → USER (декларация владения) UPDATE connections SET identity_scope = 'USER' WHERE identity_scope IN ('INSTANCE','GLOBAL');
DROP TABLE _migr_conn_canon;
